import numpy as np

# Hex embedding from user
hex_embedding = ''

# Remove '0x' prefix
if hex_embedding.startswith('0x'):
    hex_embedding = hex_embedding[2:]

# Convert hex to bytes, then to float32 array
bytes_data = bytes.fromhex(hex_embedding)
embedding_array = np.frombuffer(bytes_data, dtype=np.float32)

# Save as user_id 999
user_id = 999
np.save(f'face_database/{user_id}.npy', embedding_array)

print(f'✅ Saved user {user_id} embedding')
print(f'   Path: face_database/{user_id}.npy')
print(f'   Dimension: {len(embedding_array)}')
print(f'   Magnitude: {np.linalg.norm(embedding_array):.4f}')
